//! Java ModernNpcSpellProtocolTest emits these real-engine v24 packets.
use super::super::{
    application_protocol::Response, npc_assets::NpcAppearance, npc_presentation::Plan,
};
use super::*;
use std::io::Cursor;
const BEFORE: &str = "";
const GOLDEN: &str = "";
const FAST: &str = "";
const SECOND: &str = "";
const TELEPORT: &str = "";
const REGEN: &str = "";
const SPARSE: &str = "";
const RETIRED: &str = "";

pub(crate) fn initial() -> npc::Reply {
    read(BEFORE)
}

#[test]
fn cooperative_light_arrow_requires_v30_and_departed_caster_cannot_request() {
    use crate::modern_lito::{protocol, time_attack_protocol};
    let clock = initial().frame.unwrap().combat.world.casts[0].clone();
    for name in ["fighting", "departed"] {
        let mut reply = time_attack_protocol::tests::sample(name);
        let context = reply.echo.context;
        let f = reply.frame.as_mut().unwrap();
        f.combat.world.descriptor.as_mut().unwrap().features |=
            world::MatchDescriptor::SPELLS | world::MatchDescriptor::NPC_LIGHT_ARROW;
        f.combat.world.casts = f
            .combat
            .world
            .actors
            .iter()
            .map(|a| {
                let mut s = clock.clone();
                s.entity_id = a.entity_id;
                s
            })
            .collect();
        f.combat.npc_spells = f
            .combat
            .world
            .actors
            .iter()
            .map(|a| State::initial(a.entity_id, 3))
            .collect();
        f.validate().unwrap();
        let n = f.actors.iter().find(|n| n.alive()).unwrap();
        let mut q = Request {
            context,
            channel_id: reply.echo.channel_id,
            target: npc::Id {
                scope: f.scope,
                serial: n.serial,
            },
            sequence: 1,
            caster_life: 1,
            target_life: n.life,
        };
        assert!(q.ready_in(f));
        if name == "departed" {
            q.context.key = f.combat.world.actors[0].key;
            assert!(!q.ready_in(f));
        }
        let response = Response::Npc(reply);
        for version in [24, 25, 29, 30] {
            let ack = protocol::Ack {
                request_id: 1,
                version,
                numeric_schema: 1,
                capabilities: protocol::KNOWN_CAPABILITIES,
            };
            assert_eq!(world::descriptor_negotiated(&response, &ack), version == 30);
        }
    }
}
pub(crate) fn success() -> Reply {
    spell(GOLDEN)
}
fn bytes(hex: &str) -> Vec<u8> {
    hex.as_bytes()
        .chunks_exact(2)
        .map(|p| u8::from_str_radix(std::str::from_utf8(p).unwrap(), 16).unwrap())
        .collect()
}
fn spell(hex: &str) -> Reply {
    match app::decode_response_version(&bytes(hex), 24)
        .unwrap()
        .response
    {
        Response::NpcSpell(r) => r,
        _ => panic!("not spell"),
    }
}
fn read(hex: &str) -> npc::Reply {
    match app::decode_response_version(&bytes(hex), 24)
        .unwrap()
        .response
    {
        Response::Npc(r) => r,
        Response::NpcSpell(r) => npc::Reply {
            echo: npc::Request {
                context: r.echo.context,
                channel_id: r.echo.channel_id,
                action: npc::Action::Read,
                world: r.echo.target.scope,
                sequence: 0,
                serial: 0,
                life: 0,
            },
            status: npc::Status::Ok,
            reason: npc::Reason::None,
            frame: r.frame,
        },
        _ => panic!("not NPC"),
    }
}
#[test]
fn java_engine_spell_has_exact_request_two_lives_and_separate_mana_ledger() {
    let r = spell(GOLDEN);
    r.validate().unwrap();
    let f = r.frame.as_ref().unwrap();
    let packet = bytes(GOLDEN);
    let request = encode_request(9, &r.echo, 24).unwrap();
    assert_eq!(request.len(), 96);
    assert_eq!(&request[16..], &packet[16..96]);
    assert_eq!((r.echo.caster_life, r.echo.target_life), (1, 1));
    assert_eq!(
        f.combat.npc_spells[0].receipt.as_ref().unwrap().target,
        r.echo.target
    );
    assert_eq!(f.combat.npc_spells[0].revision, f.combat.world.revision);
    assert_eq!(f.combat.vitals[0].mp, 27);
    assert_eq!(f.combat.npc_spells[0].mp_spent, 3);
    assert_eq!(f.combat.world.casts[0].mp_spent, 0);
    assert!(f.combat.damages.is_empty());
    assert_eq!(f.combat.vitals[0].last_target_entity_id, 0);
    assert_eq!(f.combat.npc_spells[1], State::initial(2, 3));
}
#[test]
fn actual_engine_spell_denial_next_spell_teleport_and_regen_follow_without_replay() {
    let chain = [BEFORE, GOLDEN, FAST, SECOND, TELEPORT, REGEN].map(read);
    for (i, pair) in chain.windows(2).enumerate() {
        assert!(npc::follows(Some(&pair[0]), &pair[1]), "transition {i}");
        assert!(!npc::follows(Some(&pair[1]), &pair[0]), "rewind {i}");
    }
    assert_eq!(spell(FAST).reason, Reason::TooFast);
    assert_eq!(
        chain[1].frame.as_ref().unwrap().combat.npc_spells,
        chain[2].frame.as_ref().unwrap().combat.npc_spells
    );
    assert!(
        npc::follows(Some(&chain[0]), &chain[5]),
        "coalesced polling"
    );
    assert_eq!(chain[4].frame.as_ref().unwrap().combat.vitals[0].mp, 14);
    assert_eq!(chain[5].frame.as_ref().unwrap().combat.vitals[0].mp, 15);
}
#[test]
fn sparse_second_player_target_death_and_corpse_retirement_keep_receipt() {
    let a = read(SPARSE);
    let b = read(RETIRED);
    let f = a.frame.as_ref().unwrap();
    assert_eq!(f.combat.world.audience_lane, Some(1));
    assert_eq!(f.combat.npc_spells.len(), 1);
    let s = &f.combat.npc_spells[0];
    assert_eq!(s.entity_id, 2);
    assert!(s.receipt.as_ref().unwrap().death);
    assert!(f.combat.npc_spell(1).is_none());
    assert!(f.actors.iter().all(|n| n.lane == 1));
    assert_eq!(
        f.combat.npc_spells,
        b.frame.as_ref().unwrap().combat.npc_spells
    );
    assert!(npc::follows(Some(&a), &b));
}
#[test]
fn malformed_life_scope_target_mp_and_ledger_omission_are_rejected() {
    for case in 0..14 {
        let mut r = spell(GOLDEN);
        let f = r.frame.as_mut().unwrap();
        match case {
            0 => r.echo.caster_life += 1,
            1 => r.echo.target_life += 1,
            2 => r.echo.target.scope.match_id += 1,
            3 => r.echo.context.key.source_id += 1,
            4 => f.combat.vitals[0].mp += 1,
            5 => f.combat.npc_spells.clear(),
            6 => {
                f.combat.world.descriptor.as_mut().unwrap().features &=
                    !world::MatchDescriptor::NPC_LIGHT_ARROW
            }
            7 => {
                f.combat.npc_spells[0]
                    .receipt
                    .as_mut()
                    .unwrap()
                    .remaining_hp += 1
            }
            8 => {
                f.combat.npc_spells[0]
                    .receipt
                    .as_mut()
                    .unwrap()
                    .target
                    .serial = f.spawned + 1
            }
            9 => f.combat.npc_spells[0].receipt.as_mut().unwrap().lane = 1,
            10 => f.combat.npc_spells[0].caster_life = 2,
            11 => f.combat.npc_spells[0].mp_spent = i64::MAX,
            12 => f.combat.npc_spells[1].mp_cost = 0,
            _ => r.reason = Reason::NoMp,
        }
        assert!(r.validate().is_err(), "case {case}");
    }
}
#[test]
fn reserved_bytes_and_absent_receipt_payload_do_not_slip_through() {
    let original = bytes(GOLDEN);
    let signature = [1_u64, 1, 1, 6, 3, 3]
        .into_iter()
        .flat_map(u64::to_be_bytes)
        .collect::<Vec<_>>();
    let start = original
        .windows(signature.len())
        .position(|w| w == signature)
        .unwrap();
    for at in [
        start - 6,
        start - 1,
        start + 74,
        start + 79,
        start + 120 + 80,
        start + 120 + 119,
        37,
        38,
        39,
        99,
    ] {
        let mut bad = original.clone();
        bad[at] = 1;
        assert!(
            app::decode_response_version(&bad, 24).is_err(),
            "offset {at}"
        );
    }
    for length in 0..original.len() {
        assert!(
            app::decode_response_version(&original[..length], 24).is_err(),
            "truncated {length}"
        );
    }
    let mut trailing = original.clone();
    trailing.push(0);
    assert!(app::decode_response_version(&trailing, 24).is_err());
}
#[test]
fn old_peers_reject_v24_from_header_before_reading_body_and_streams_remain_exact() {
    let b = bytes(GOLDEN);
    for version in 1..24 {
        let mut reader = Cursor::new(b.as_slice());
        assert!(app::read_response_version(&mut reader, version).is_err());
        assert_eq!(reader.position(), 16, "version {version}");
        assert!(encode_request(1, &spell(GOLDEN).echo, version).is_err());
    }
    let mut stream = b.clone();
    stream.extend(&b);
    let mut cursor = Cursor::new(stream);
    assert_eq!(
        app::read_response_version(&mut cursor, 24).unwrap(),
        app::decode_response_version(&b, 24).unwrap()
    );
    assert_eq!(cursor.position(), b.len() as u64);
    let mut header = b[..16].to_vec();
    header[4..8].copy_from_slice(&(npc::MAX_FRAME_BYTES as u32 + 1).to_be_bytes());
    let mut reader = Cursor::new(header);
    assert!(app::read_response_version(&mut reader, 24).is_err());
    assert_eq!(reader.position(), 16);
}
#[test]
fn independent_full_width_identity_and_absent_unavailable_reply_are_bounded() {
    let mut r = spell(GOLDEN).echo;
    r.context.key.object_id = 9_007_199_254_740_993;
    r.context.epoch = u64::MAX;
    r.caster_life = 19;
    r.target_life = 29;
    r.sequence = i64::MAX as u64;
    let request = encode_request(1, &r, 24).unwrap();
    assert_eq!(request.len(), 96);
    assert_eq!(
        u64::from_be_bytes(request[20..28].try_into().unwrap()),
        9_007_199_254_740_993
    );
    let mut packet = app::header(1, RESULT_KIND, 100).unwrap();
    packet.extend(&request[16..]);
    packet.extend([3, 1, 0, 0]);
    let Response::NpcSpell(reply) = app::decode_response_version(&packet, 24).unwrap().response
    else {
        panic!()
    };
    assert_eq!(reply.echo, r);
    assert!(reply.frame.is_none());
    for at in [96, 97, 98, 99] {
        let mut bad = packet.clone();
        bad[at] = 255;
        assert!(app::decode_response_version(&bad, 24).is_err());
    }
    r.target_life = 0;
    assert!(encode_request(1, &r, 24).is_err());
}
#[test]
fn one_shared_sequence_cannot_commit_both_teleport_and_npc_spell() {
    let mut a = read(BEFORE).frame.unwrap().combat;
    let mut b = read(GOLDEN).frame.unwrap().combat;
    a.world.casts[0].request_sequence = 2;
    b.world.casts[0].request_sequence = 3;
    b.world.casts[0].cast_count = 1;
    b.npc_spells[0].request_sequence = 3;
    assert!(
        !follows(&a, &b),
        "old denied requests cannot pay for two new successful casts"
    );
    b.world.casts[0].request_sequence = 4;
    b.npc_spells[0].request_sequence = 4;
    assert!(
        follows(&a, &b),
        "two distinct new requests remain admissible"
    );
}
#[test]
fn no_regen_mana_totals_include_npc_casts_and_cannot_refund_them() {
    let mut a = read(BEFORE).frame.unwrap().combat;
    let mut b = read(GOLDEN).frame.unwrap().combat;
    for f in [&mut a, &mut b] {
        f.regen.clear();
        f.world.descriptor.as_mut().unwrap().features &= !world::MatchDescriptor::REGEN;
        f.validate().unwrap();
    }
    assert!(combat::vitals_follow(&a, &b));
    assert!(super::super::spell_protocol::mp_follows(&a, &b, 0));
    b.vitals[0].mp += 3;
    assert!(b.validate().is_err());
    assert!(!super::super::spell_protocol::mp_follows(&a, &b, 0));
}
#[test]
fn snapshots_cannot_mutate_a_receipt_or_bypass_explicit_magic_preflight() {
    let a = read(GOLDEN);
    let mut b = read(FAST);
    b.frame.as_mut().unwrap().combat.npc_spells[0]
        .receipt
        .as_mut()
        .unwrap()
        .critical = false;
    b.validate().unwrap();
    assert!(
        !npc::follows(Some(&a), &b),
        "same cast count cannot rewrite receipt"
    );
    Plan::from_reply(&a).unwrap().validate(&a).unwrap();
    let frame = a.frame.as_ref().unwrap();
    let trusted = Plan::new(
        frame.scope,
        frame
            .resources
            .as_ref()
            .unwrap()
            .iter()
            .map(|g| NpcAppearance::new(*g).unwrap())
            .collect(),
    )
    .unwrap();
    assert!(
        trusted.validate(&a).is_err(),
        "a trusted NPC-only plan cannot bypass missing magic capability"
    );
}

#[test]
fn exact_cast_transition_and_typed_snapshot_bridge_do_not_accept_extra_successes() {
    let before = initial();
    let first = success();
    let fast = spell(FAST);
    let second = spell(SECOND);
    assert!(first.echo.ready_in(before.frame.as_ref().unwrap()));
    assert!(first.confirms(&first.echo));
    assert!(confirms_transition(before.frame.as_ref().unwrap(), &first));
    assert!(confirms_transition(first.frame.as_ref().unwrap(), &fast));
    assert!(confirms_transition(fast.frame.as_ref().unwrap(), &second));
    assert!(!confirms_transition(
        before.frame.as_ref().unwrap(),
        &second
    ));
    assert!(!confirms_transition(first.frame.as_ref().unwrap(), &first));
    for r in [&first, &fast, &second] {
        r.npc_reply().validate().unwrap();
    }
    assert!(npc::follows(Some(&before), &first.npc_reply()));
    let mut forged = fast.clone();
    forged.frame.as_mut().unwrap().combat.npc_spells[0]
        .receipt
        .as_mut()
        .unwrap()
        .critical = false;
    forged.validate().unwrap();
    assert!(!confirms_transition(first.frame.as_ref().unwrap(), &forged));
}

#[test]
fn typed_input_requires_current_npc_scope_both_lives_and_shared_sequence() {
    let before = initial().frame.unwrap();
    let good = success().echo;
    for field in 0..6 {
        let mut bad = good;
        match field {
            0 => bad.target.scope.generation += 1,
            1 => bad.target.serial += 999,
            2 => bad.target_life += 1,
            3 => bad.caster_life += 1,
            4 => bad.sequence += 1,
            _ => bad.context.key.source_id += 1,
        }
        assert!(!bad.ready_in(&before));
    }
    let mut no_resources = before.clone();
    no_resources.resources = None;
    assert!(!good.ready_in(&no_resources));
}
